import{_ as t,o as r,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-02-26:: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-02-26:: Crimson SeaStor OSD Weekly Meeting","date":"2019-02-26T00:00:00.000Z","updated":"2019-04-17T00:00:00.000Z","tags":["Ceph集群操作","Recovery State Machine","Ceph消息传递性能优化","Ceph消息传递协议","Ceph集群状态监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-02-26_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-02-26_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),a={name:"posts/2019/2019-02-26_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function i(n,e,s,_,g,h){return r(),o("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>[会议时间]</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>[参会人员名单]</p><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. Recovery State Machine</strong></p><ul><li><strong>议题</strong>：研发人员汇报了关于恢复状态机的最小实现工作，指出许多功能和特性依赖于状态机，且该状态机与scrubber、recovery等特性紧密耦合。</li><li><strong>讨论</strong>：由于状态机的复杂性，预计需要更多时间进行测试和改进。</li><li><strong>决定</strong>：继续推进状态机开发，并计划进行更深入的研究。</li></ul><p><strong>2. Ceph集群操作</strong></p><ul><li><strong>议题</strong>：讨论了如何使用现有的OSD进行迁移测试。</li><li><strong>讨论</strong>：使用现有的OSD进行迁移测试，需要准备OSD并启动，可手动执行迁移命令或使用提供的图表进行操作，讨论了潜在问题如错误处理和状态跟踪。</li><li><strong>决定</strong>：继续研究使用现有OSD进行迁移的方案，并解决相关问题。</li></ul><p><strong>3. Ceph消息传递</strong></p><ul><li><strong>议题</strong>：讨论了Ceph消息传递的性能优化。</li><li><strong>讨论</strong>：消息传递模块已合并一些性能优化，包括协议级别抽象和队列策略优化。讨论了使用CSTAR技术对消息传递模块进行优化的可能性。</li><li><strong>决定</strong>：继续研究CSTAR技术对消息传递模块的优化，并计划进行性能测试。</li></ul><p><strong>4. 其他事项</strong></p><ul><li><strong>议题</strong>：讨论了字幕翻译和总结工作。</li><li><strong>讨论</strong>：翻译和总结工作进展顺利，但需要进一步优化流程。</li><li><strong>决定</strong>：继续优化翻译和总结工作流程。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>Recovery State Machine</strong>： <ul><li>完成状态机的最小实现，并进行测试和改进。</li></ul></li><li><strong>Ceph集群操作</strong>： <ul><li>研究使用现有OSD进行迁移的方案，并解决相关问题。</li></ul></li><li><strong>Ceph消息传递</strong>： <ul><li>继续研究CSTAR技术对消息传递模块的优化。</li><li>进行性能测试，以评估优化效果。</li></ul></li><li><strong>字幕翻译和总结</strong>： <ul><li>优化翻译和总结工作流程。</li></ul></li></ul><h4 id="下次会议时间" tabindex="-1">下次会议时间： <a class="header-anchor" href="#下次会议时间" aria-label="Permalink to &quot;下次会议时间：&quot;">​</a></h4><p>[下次会议时间]</p>',18)])])}const d=t(a,[["render",i]]);export{u as __pageData,d as default};
